{
 readonly string page;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;
 JsonObject? snapshot,analysis;JsonArray? layoutRect,exemplarRect;string? sourcePath,cropPath;bool busy,loading;
 sealed record Row(JsonObject Data,string Label);
 sealed record LanguageRow(JsonObject Data,string Id,string Name,string Iso,string Level);
 int languageOffset,languageTotal;bool languagesMore;JsonObject? languageSnapshot;
 JsonObject? packageSnapshot;JsonArray? wordRect;int wordStart=-1,wordEnd=-1;
 public string? RequestedRecognitionAnnotation{get;private set;}
 static string T(string text)=>Localizer.Text(text);
 Task<JsonNode> Call(string command,JsonObject args)=>worker(command,args,default);
 static string LanguageLevel(string value)=>T(value switch{"language"=>"Мова","dialect"=>"Діалект","family"=>"Мовна сім’я",_=>"Невідомо"});
 async Task LoadLanguages(int offset)
 {languageSnapshot=(await Call("historical_languages",new(){["query"]=LanguageQuery.Text,["limit"]=25,["offset"]=offset})).AsObject();languageOffset=languageSnapshot["offset"]!.GetValue<int>();languageTotal=languageSnapshot["total"]!.GetValue<int>();languagesMore=languageSnapshot["has_more"]!.GetValue<bool>();LanguageRows.ItemsSource=Array(languageSnapshot,"rows").Select(n=>new LanguageRow(n!.AsObject(),Value(n,"id"),Value(n,"name"),Value(n,"iso"),LanguageLevel(Value(n,"level")))).ToList();LanguageRows.SelectedIndex=LanguageRows.Items.Count>0?0:-1;if(LanguageRows.Items.Count==0)LanguageDetails.Text=T("За цим запитом записів немає.");LanguageRange.Text=$"{(languageTotal==0?0:languageOffset+1)}–{languageOffset+LanguageRows.Items.Count} / {languageTotal}";PreviousLanguages.IsEnabled=languageOffset>0;NextLanguages.IsEnabled=languagesMore;var source=languageSnapshot["dataset"];LanguageProvenance.Text=Value(source,"notes")+"\n"+Value(source,"citation")+"\n"+T("Ліцензія")+": "+Value(source,"license")+" · "+Value(source,"license_url")+"\n"+T("Походження даних")+": "+Value(source,"provenance_url")+"\n"+T("Дата отримання")+": "+Value(source,"retrieved_date")+"\n"+T("Версія джерела")+": "+Value(source,"commit_sha")+"\n"+Value(source,"scope");}
 async void FindLanguages(object sender,RoutedEventArgs e)=>await Run(()=>LoadLanguages(0));
 async void LanguageQueryKey(object sender,System.Windows.Input.KeyEventArgs e){if(e.Key==System.Windows.Input.Key.Enter){e.Handled=true;await Run(()=>LoadLanguages(0));}}
 async void PreviousLanguagePage(object sender,RoutedEventArgs e)=>await Run(()=>LoadLanguages(Math.Max(0,languageOffset-25)));
 async void NextLanguagePage(object sender,RoutedEventArgs e)=>await Run(()=>LoadLanguages(languageOffset+25));
 void SelectLanguage(object sender,SelectionChangedEventArgs e){if(LanguageRows.SelectedItem is LanguageRow row)LanguageDetails.Text=row.Name+"\nGlottocode: "+row.Id+" · ISO 639-3: "+row.Iso+" · "+row.Level+"\n"+Value(row.Data,"resource_url");}
 async Task SmokeLanguages()
 {Tabs.SelectedIndex=4;LanguageQuery.Text="Latin";await LoadLanguages(0);if(!LanguageRows.Items.Cast<LanguageRow>().Any(r=>r.Iso=="lat"&&r.Id=="lati1261"))throw new Exception("Latin registry entry missing");LanguageRows.SelectedItem=LanguageRows.Items.Cast<LanguageRow>().First(r=>r.Iso=="lat"&&r.Id=="lati1261");SmokeCapture.Save(this,"historical-ui","languages-latin.png");LanguageQuery.Clear();await LoadLanguages(0);var first=LanguageRows.Items.Cast<LanguageRow>().Select(r=>r.Id).ToHashSet();if(!languagesMore)throw new Exception("Language catalogue has no next page");await LoadLanguages(25);if(LanguageRows.Items.Cast<LanguageRow>().Any(r=>first.Contains(r.Id))||LanguageRows.Items.Count>25)throw new Exception("Language pages overlap or exceed bound");SmokeCapture.Save(this,"historical-ui","languages-page2.png");System.IO.File.WriteAllText(System.IO.Path.Combine(Environment.GetEnvironmentVariable("ARCHIVEREADER_DATA")!,"historical-language-smoke.json"),new JsonObject{["latin_found"]=true,["page_limit"]=25,["total"]=languageTotal,["pages_overlap"]=false,["dataset"]=languageSnapshot?["dataset"]?.DeepClone()}.ToJsonString());await LoadLanguages(0);if(!LanguageRows.Items.Cast<LanguageRow>().Select(r=>r.Id).ToHashSet().SetEquals(first))throw new Exception("Language pagination is not stable");}
 async Task SmokeWord()
 {Tabs.SelectedIndex=2;WordPanel.IsExpanded=true;if(WordTokens.Items.Count==0)throw new Exception("Fixture has no literal token");WordTokens.SelectedIndex=0;var reading=Reading.Text;var literal=Literal.Text;var signature=(await Call("historical_get",new(){["page"]=page}))["signature"]?.ToString();await ShowWord();if(Reading.Text!=reading||Literal.Text!=literal||WordLiteral.Text.Length==0)throw new Exception("Word inspection changed literal reading");if((await Call("historical_get",new(){["page"]=page}))["signature"]?.ToString()!=signature)throw new Exception("Word inspection mutated source state");WordPanel.BringIntoView();await Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.ContextIdle);SmokeCapture.Save(this,"historical-ui","word-inspection.png");System.IO.File.WriteAllText(System.IO.Path.Combine(Environment.GetEnvironmentVariable("ARCHIVEREADER_DATA")!,"historical-word-smoke.json"),new JsonObject{["literal_unchanged"]=true,["reading_unchanged"]=true,["state_unchanged"]=true,["word_literal"]=WordLiteral.Text,["manual_rect"]=false,["requested_recognition"]=RequestedRecognitionAnnotation}.ToJsonString());}
 string? Annotation=>(Regions.SelectedItem as Row)?.Data["id"]?.ToString();
 public HistoricalReadingWindow(string page,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker)
 {this.page=page;this.worker=worker;InitializeComponent();Loaded+=async(_,_)=>{Localizer.Apply(this,Localizer.Language);foreach(var column in LanguageRows.Columns)column.Header=T(column.Header?.ToString()??"");await Run(async()=>{sourcePath=(await Call("render",new(){["id"]=page,["whole"]=true,["full"]=true,["preprocess"]="original"}))["path"]!.ToString();ShowImage(LayoutPreview,sourcePath);await Reload();await LoadLanguages(0);if(Environment.GetCommandLineArgs().Contains("--smoke-historical")){await LoadProposals();Tabs.IsEnabled=true;for(int i=0;i<Tabs.Items.Count;i++){Tabs.SelectedIndex=i;await Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.ContextIdle);SmokeCapture.Save(this,"historical-ui",$"tab-{i}.png");}Tabs.SelectedIndex=3;UpdateLayout();StructureScroll.ScrollToEnd();SmokeCapture.Save(this,"historical-ui","exemplar.png");Tabs.SelectedIndex=2;UpdateLayout();AnalysisScroll.ScrollToEnd();SmokeCapture.Save(this,"historical-ui","decision.png");Tabs.SelectedIndex=1;Terms.SelectedItem=Terms.Items.Cast<Row>().FirstOrDefault(r=>r.Data["reference"] is JsonObject);UpdateLayout();LexiconScroll.ScrollToEnd();SmokeCapture.Save(this,"historical-ui","term-reference.png");var signature=snapshot?["signature"]?.ToString();if(SourceCatalog.Items.Count==0)throw new Exception("Reference catalogue missing in smoke test");var oldForm=Form.Text;InsertReferenceSource(this,new RoutedEventArgs());if(Form.Text!=oldForm||ReferenceLocator.Text.Length!=0||ReferenceChecked.IsChecked==true||TermChecked.IsChecked==true)throw new Exception("Source picker changed a rule or checked itself");ReferenceCatalogPanel.BringIntoView();SmokeCapture.Save(this,"historical-ui","reference-catalog.png");LoadReferenceExample(this,new RoutedEventArgs());if((await Call("historical_get",new(){["page"]=page}))["signature"]?.ToString()!=signature)throw new Exception("Reference example mutated source state");if(TermChecked.IsChecked==true||ReferenceChecked.IsChecked==true)throw new Exception("Reference example marked itself checked");SmokeCapture.Save(this,"historical-ui","reference-example.png");await SmokeLanguages();await SmokeWord();Close();}});};}
 async Task Run(Func<Task> action){if(busy)return;busy=true;Tabs.IsEnabled=false;try{await action();}catch(Exception ex){Status.Text=T(ex.Message);if(Environment.GetCommandLineArgs().Contains("--smoke-historical")){System.IO.File.WriteAllText(System.IO.Path.Combine(Environment.GetEnvironmentVariable("ARCHIVEREADER_DATA")!,"historical-error.txt"),ex.ToString());Application.Current.Shutdown(1);}}finally{busy=false;Tabs.IsEnabled=true;}}
 static string Value(JsonNode? node,string key)=>node?[key]?.ToString()??"";
 static JsonArray Array(JsonNode? node,string key)=>node?[key] as JsonArray??new JsonArray();
 static string Short(string text)=>text.Length>65?text[..65]+"…":text;
 async Task ReloadKeepingReading(){var annotation=Annotation;var reading=Reading.Text;var interpretation=Interpretation.Text;var note=DecisionNote.Text;var uncertain=Uncertain.IsChecked;await Reload();if(Annotation==annotation){Reading.Text=reading;Interpretation.Text=interpretation;DecisionNote.Text=note;Uncertain.IsChecked=uncertain;}DecisionChecked.IsChecked=false;}
 void RequestParentRecognition(object sender,RoutedEventArgs e){if(Annotation==null){Status.Text=T("Спочатку виберіть розмічений рядок.");return;}RequestedRecognitionAnnotation=Annotation;DialogResult=true;}
 async Task LoadPackage(){packageSnapshot=(await Call("historical_package_get",new(){["page"]=page})).AsObject();var profile=packageSnapshot["profile"];PackageContext.Text=Value(profile,"origin")+" · "+Value(profile,"period")+" · "+Value(profile,"writer")+"\n"+(profile?["languages"] is JsonArray languages?string.Join(", ",languages.Select(n=>n?.ToString())):Value(profile,"languages"));PackageConfigured.IsChecked=packageSnapshot["configured"]?.GetValue<bool>()==true;PackageTerms.ItemsSource=Array(packageSnapshot,"available_terms").Select(n=>new Row(n!.AsObject(),Value(n,"form")+" → "+Value(n,"lemma")+" ("+Value(n,"language")+")"+(n?["stale"]?.GetValue<bool>()==true?" · "+T("Застаріла підказка"):""))).ToList();PackageSources.ItemsSource=Array(packageSnapshot,"reference_sources").Select(n=>new Row(n!.AsObject(),Value(n,"title"))).ToList();foreach(var row in PackageTerms.Items.Cast<Row>())if(Array(packageSnapshot,"term_ids").Any(n=>n?.ToString()==Value(row.Data,"id")))PackageTerms.SelectedItems.Add(row);foreach(var row in PackageSources.Items.Cast<Row>())if(Array(packageSnapshot,"source_ids").Any(n=>n?.ToString()==Value(row.Data,"id")))PackageSources.SelectedItems.Add(row);PackageNotes.Text=Value(packageSnapshot,"notes");PackageChecked.IsChecked=false;PackageWarnings.Text=packageSnapshot["conflicting_book_values"]?.GetValue<bool>()==true?T("Складові книги мають різні пакети. Перевірте вибір перед збереженням."):"";}
 async void SavePackage(object sender,RoutedEventArgs e)=>await Run(async()=>{await Call("historical_package_save",new(){["page"]=page,["expected"]=packageSnapshot?["signature"]?.ToString(),["configured"]=PackageConfigured.IsChecked==true,["term_ids"]=new JsonArray(PackageTerms.SelectedItems.Cast<Row>().Select(r=>JsonValue.Create(Value(r.Data,"id"))).ToArray()),["source_ids"]=new JsonArray(PackageSources.SelectedItems.Cast<Row>().Select(r=>JsonValue.Create(Value(r.Data,"id"))).ToArray()),["notes"]=PackageNotes.Text,["checked"]=PackageChecked.IsChecked==true});await ReloadKeepingReading();Status.Text=T("Збережено");});
 void SetWordSpan(int start,int end){wordStart=start;wordEnd=end;wordRect=null;WordSpan.Text=$"{start}–{end}";WordGeometry.Text=T("Показано весь рядок: межі слова не визначено.");WordLiteral.Text="";WordEvidence.Clear();WordCrop.Source=null;}
 void SelectWordToken(object sender,SelectionChangedEventArgs e){if(WordTokens.SelectedItem is Row row)SetWordSpan(row.Data["start"]!.GetValue<int>(),row.Data["end"]!.GetValue<int>());}
 void UseLiteralSelection(object sender,RoutedEventArgs e){if(Literal.SelectionLength>0){WordTokens.SelectedIndex=-1;var start=Literal.SelectionStart;var end=start+Literal.SelectionLength;if(start>0&&start<Literal.Text.Length&&char.IsLowSurrogate(Literal.Text[start])&&char.IsHighSurrogate(Literal.Text[start-1]))start--;if(end<Literal.Text.Length&&char.IsLowSurrogate(Literal.Text[end])&&end>0&&char.IsHighSurrogate(Literal.Text[end-1]))end++;SetWordSpan(Literal.Text[..start].EnumerateRunes().Count(),Literal.Text[..end].EnumerateRunes().Count());}else Status.Text=T("Спочатку виділіть буквальний фрагмент тексту.");}
 async Task ShowWord(){if(Annotation==null||wordStart<0||wordEnd<=wordStart){Status.Text=T("Спочатку виберіть слово або буквальний фрагмент.");return;}var result=await Call("historical_word",new(){["page"]=page,["annotation"]=Annotation,["start"]=wordStart,["end"]=wordEnd,["rect"]=wordRect?.DeepClone()});WordLiteral.Text=Value(result,"literal");ShowImage(WordCrop,Value(result["crop"],"path"));WordGeometry.Text=T(Value(result["crop"],"geometry_basis")=="human_manual_word_rect"?"Показано фрагмент, виділений людиною. Відповідність рисок слову потребує перевірки.":"Показано весь рядок: межі слова не визначено.");WordEvidence.Text=string.Join("\n",Array(result,"tokens").Select(token=>Value(token,"literal")+" → "+(Array(token,"matches").Count==0?T("Немає словникової підказки"):string.Join("\n",Array(token,"matches").Select(MatchDescription)))))+"\n\n"+string.Join("\n",Array(result,"alternatives").Select(n=>Value(n,"model")+": ["+Value(n?["selected_span"],"text")+"] · "+T("Текстове зіставлення; межі на скані не визначено.")+"\n"+Value(n,"text")))+"\n\n"+string.Join("\n",Array(result,"context").Select(n=>Value(n,"text")))+"\n"+string.Join("\n",Array(result,"warnings").Select(n=>Warning(n?.ToString()??"")));}
 async void InspectWord(object sender,RoutedEventArgs e)=>await Run(ShowWord);
 void PickWordCrop(object sender,RoutedEventArgs e){if(cropPath==null||analysis?["original"]?["rect"] is not JsonArray parent||wordStart<0){Status.Text=T("Спочатку виберіть слово або буквальний фрагмент.");return;}var picker=new RegionPicker(cropPath){Owner=this};if(picker.ShowDialog()!=true||picker.Bounds is not JsonArray rect)return;wordRect=new JsonArray(parent[0]!.GetValue<double>()+rect[0]!.GetValue<double>()*parent[2]!.GetValue<double>(),parent[1]!.GetValue<double>()+rect[1]!.GetValue<double>()*parent[3]!.GetValue<double>(),rect[2]!.GetValue<double>()*parent[2]!.GetValue<double>(),rect[3]!.GetValue<double>()*parent[3]!.GetValue<double>());WordGeometry.Text=T("Показано фрагмент, виділений людиною. Відповідність рисок слову потребує перевірки.");ShowImage(WordCrop,cropPath,rect);}
 static string ReferenceTypeLabel(string value)=>value switch{"archive_tutorial_pdf"=>T("Архівний навчальний матеріал (PDF)"),"catalogued_reference"=>T("Довідкове джерело: тип потребує перевірки"),"university_guidelines"=>T("Університетські настанови"),"university_reference_database"=>T("Університетська довідкова база"),"university_tutorial"=>T("Університетський навчальний матеріал"),"bibliography"=>T("Бібліографія"),"comparative_wordlists"=>T("Порівняльні списки слів"),"dictionary_collection"=>T("Збірка словників"),"grammar_collection"=>T("Збірка граматик"),"historical_language_portal"=>T("Портал історичних мов"),"language_catalog"=>T("Каталог мов"),"metadata_search"=>T("Пошук бібліографічних відомостей"),"text_corpus"=>T("Корпус текстів"),_=>value};
 static string ReferenceDescription(JsonNode? reference){if(reference is not JsonObject r||r.Count==0)return "";return "\n"+T("Довідкове джерело")+": "+Value(r,"title")+"\n"+Value(r,"url")+"\n"+T("Місце у джерелі")+": "+Value(r,"locator")+"\n"+T("Тип довідкового джерела")+": "+ReferenceTypeLabel(Value(r,"resource_type"))+"\n"+T("Час створення твору")+": "+Value(r,"work_period")+"\n"+T("Дата рукописного примірника")+": "+Value(r,"witness_period")+"\n"+T("Час видання або опису")+": "+Value(r,"edition_period")+"\n"+T("Межі застосування: мова, регіон, тип документа")+": "+Value(r,"scope")+"\n"+T("Автентичність і характер правила")+": "+Value(r,"authenticity");}
 static string MatchDescription(JsonNode? match)=>Value(match,"lemma")+" → "+Value(match,"meaning")+" ("+Value(match,"language")+")"+ReferenceDescription(match?["reference"])+string.Join("",Array(match,"equivalents").Select(e=>"\n≈ "+Value(e,"form")+" → "+Value(e,"meaning")+" ("+Value(e,"language")+")"+ReferenceDescription(e?["reference"])));
 JsonObject? TermReference(){if(new[]{ReferenceTitle,ReferenceUrl,ReferenceLocator,ReferenceType,ReferenceWorkPeriod,ReferenceWitnessPeriod,ReferenceEditionPeriod,ReferenceScope,ReferenceAuthenticity}.All(f=>string.IsNullOrWhiteSpace(f.Text)))return null;return new(){["title"]=ReferenceTitle.Text,["url"]=ReferenceUrl.Text,["locator"]=ReferenceLocator.Text,["resource_type"]=ReferenceType.Text,["work_period"]=ReferenceWorkPeriod.Text,["witness_period"]=ReferenceWitnessPeriod.Text,["edition_period"]=ReferenceEditionPeriod.Text,["scope"]=ReferenceScope.Text,["authenticity"]=ReferenceAuthenticity.Text,["checked"]=ReferenceChecked.IsChecked==true};}
 void ReadReference(JsonNode? r){ReferenceTitle.Text=Value(r,"title");ReferenceUrl.Text=Value(r,"url");ReferenceLocator.Text=Value(r,"locator");ReferenceType.Text=ReferenceTypeLabel(Value(r,"resource_type"));ReferenceWorkPeriod.Text=Value(r,"work_period");ReferenceWitnessPeriod.Text=Value(r,"witness_period");ReferenceEditionPeriod.Text=Value(r,"edition_period");ReferenceScope.Text=Value(r,"scope");ReferenceAuthenticity.Text=Value(r,"authenticity");ReferenceChecked.IsChecked=false;}
 static string Role(string? role)=>T(role switch{"text"=>"Текст","table"=>"Таблиця","illustration"=>"Ілюстрація","caption"=>"Підпис","damage"=>"Пошкодження",_=>"Невідомо"});
 static string Warning(string code)=>T(code switch{"stale_comparison_ignored"=>"Застаріле порівняння пропущено.","damage_overlap_no_ground_truth"=>"Ділянка пошкоджена: це не навчальний еталон.","saved_model_variants_disagree"=>"Збережені моделі прочитали по-різному.","context_is_human_lexicon_not_learned_grammar"=>"Підказки взято з ручного словника.","unknown_words_are_not_errors"=>"Невідоме слово не означає помилку.","no_inferred_nationality_or_language"=>"Мова й походження не вгадуються.","reference_scope_requires_human_review"=>"Перевірте межі застосування довідкового джерела.",_=>"Потребує ручної перевірки."});
 async Task Reload()
 {
  var selected=Annotation;snapshot=(await Call("historical_get",new(){["page"]=page})).AsObject();loading=true;
  var profile=snapshot["profile"]?["values"];Origin.Text=Value(profile,"origin");Period.Text=Value(profile,"period");Institution.Text=Value(profile,"institution");Rite.Text=Value(profile,"rite");Script.Text=Value(profile,"script");Writer.Text=Value(profile,"writer");Languages.Text=profile?["languages"] is JsonArray langs?string.Join(", ",langs.Select(n=>n?.ToString())):Value(profile,"languages");ProfileNotes.Text=Value(profile,"notes");
  Terms.ItemsSource=Array(snapshot,"terms").Select(n=>new Row(n!.AsObject(),Value(n,"form")+" → "+Value(n,"lemma")+" → "+Value(n,"meaning")+(n?["stale"]?.GetValue<bool>()==true?" · "+T("Застаріла підказка"):""))).ToList();
  SourceCatalog.ItemsSource=Array(snapshot,"reference_sources").Select(n=>new Row(n!.AsObject(),Value(n,"title"))).ToList();SourceCatalog.SelectedIndex=SourceCatalog.Items.Count>0?0:-1;if(SourceCatalog.Items.Count==0)SourceCatalogStatus.Text=T("Каталог недоступний. Довідкове джерело можна ввести вручну.");
  Regions.ItemsSource=Array(snapshot,"regions").Where(n=>Value(n,"kind") is "line" or "entry").Select(n=>new Row(n!.AsObject(),T(Value(n,"kind")=="line"?"Рядок":"Запис")+" · "+Short(Value(n,"text")))).ToList();Regions.SelectedItem=Regions.Items.Cast<Row>().FirstOrDefault(r=>Value(r.Data,"id")==selected)??Regions.Items.Cast<Row>().FirstOrDefault();
  Layouts.ItemsSource=Array(snapshot,"layout").Select(n=>new Row(n!.AsObject(),Role(Value(n,"role"))+" · "+Value(n,"note"))).ToList();
  Exemplars.ItemsSource=Array(snapshot,"exemplars").Select(n=>new Row(n!.AsObject(),Value(n,"label")+" · "+Value(n,"note")+(n?["stale"]?.GetValue<bool>()==true?" · "+T("Джерело змінилося"):""))).ToList();
  loading=false;await LoadPackage();await Analyze();if(Exemplars.Items.Count>0)Exemplars.SelectedIndex=0;
 }
 async Task Analyze()
 {
  analysis=null;cropPath=null;exemplarRect=null;wordRect=null;wordStart=-1;wordEnd=-1;WordTokens.ItemsSource=null;WordLiteral.Clear();WordEvidence.Clear();WordCrop.Source=null;ExemplarBounds.Text="";SourceCrop.Source=null;ExemplarPreview.Source=null;DecisionChecked.IsChecked=false;
  if(Annotation==null){Literal.Text=T("На сторінці ще немає розмічених рядків або записів.");return;}
  analysis=(await Call("historical_analyze",new(){["page"]=page,["annotation"]=Annotation})).AsObject();cropPath=(await Call("region_crop",new(){["id"]=page,["annotation"]=Annotation}))["path"]!.ToString();ShowImage(SourceCrop,cropPath);
  Literal.Text=Value(analysis["original"],"text");WordTokens.ItemsSource=Array(analysis,"tokens").Select(n=>new Row(n!.AsObject(),Value(n,"literal")+" · "+Value(n,"start")+"–"+Value(n,"end"))).ToList();Alternatives.Text=string.Join("\n\n",Array(analysis,"alternatives").Select(n=>Value(n,"model")+": "+Value(n,"text")));if(Alternatives.Text.Length==0)Alternatives.Text=T("Для цього фрагмента ще немає збережених варіантів моделей.");
  Tokens.Text=string.Join("\n",Array(analysis,"tokens").Select(token=>Value(token,"literal")+" → "+(Array(token,"matches").Count==0?T("Немає словникової підказки"):string.Join(" / ",Array(token,"matches").Select(match=>MatchDescription(match))))));
  Context.Text=string.Join("\n",Array(analysis,"context").Select(n=>Value(n,"text")))+"\n"+string.Join("\n",Array(analysis,"warnings").Select(n=>Warning(n?.ToString()??"")));
  HandReferences.ItemsSource=Array(analysis,"exemplars").Select(n=>new Row(n!.AsObject(),Value(n,"label")+" · "+Value(n,"hand_label")+(n?["stale"]?.GetValue<bool>()==true?" · "+T("Джерело змінилося"):""))).ToList();HandReferences.SelectedIndex=HandReferences.Items.Count>0?0:-1;if(HandReferences.Items.Count==0){HandSample.Source=null;HandStatus.Text=T("Для цього позначення почерку зразків немає.");}
  var saved=Array(snapshot,"decisions").FirstOrDefault(n=>Value(n,"annotation")==Annotation);Reading.Text=saved==null?Literal.Text:Value(saved,"reading");Interpretation.Text=Value(saved,"interpretation");DecisionNote.Text=Value(saved,"note");Uncertain.IsChecked=saved?["uncertain"]?.GetValue<bool>()??true;if(saved?["stale"]?.GetValue<bool>()==true)Context.Text+="\n"+T("Збережене прочитання потребує повторної перевірки.");
 }
 async void SelectRegion(object sender,SelectionChangedEventArgs e){if(!loading)await Run(Analyze);}
 async void SaveProfile(object sender,RoutedEventArgs e)=>await Run(async()=>{await Call("historical_profile",new(){["page"]=page,["expected"]=snapshot?["profile"]?["signature"]?.ToString(),["values"]=new JsonObject{["origin"]=Origin.Text,["period"]=Period.Text,["institution"]=Institution.Text,["rite"]=Rite.Text,["script"]=Script.Text,["writer"]=Writer.Text,["languages"]=Languages.Text,["notes"]=ProfileNotes.Text}});await Reload();Status.Text=T("Збережено");});
 void SelectTerm(object sender,SelectionChangedEventArgs e){if(Terms.SelectedItem is not Row row)return;var n=row.Data;Form.Text=Value(n,"form");Lemma.Text=Value(n,"lemma");Meaning.Text=Value(n,"meaning");Concept.Text=Value(n,"concept");TermLanguage.Text=Value(n,"language");TermPeriod.Text=Value(n,"period");TermWriter.Text=Value(n,"writer");TermNote.Text=Value(n,"note");ReadReference(n["reference"]);TermKind.SelectedItem=TermKind.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>i.Tag.ToString()==Value(n,"kind"))??TermKind.Items[0];TermChecked.IsChecked=false;}
 void ClearTerm(object sender,RoutedEventArgs e){Terms.SelectedItem=null;ReadReference(null);foreach(var field in new[]{Form,Lemma,Meaning,Concept,TermLanguage,TermPeriod,TermWriter,TermNote})field.Clear();TermChecked.IsChecked=false;}
 void SelectReferenceSource(object sender,SelectionChangedEventArgs e){if(SourceCatalog.SelectedItem is Row row){var status=Value(row.Data,"verification");var colon=status.IndexOf(':');SourceCatalogStatus.Text=(colon>=0?status[(colon+1)..].Trim():status)+"\n"+Value(row.Data,"scope");}}
 void InsertReferenceSource(object sender,RoutedEventArgs e){if(SourceCatalog.SelectedItem is not Row row)return;ReadReference(row.Data);ReferenceLocator.Clear();ReferenceChecked.IsChecked=false;TermChecked.IsChecked=false;Status.Text=T("Вставлено лише відомості про джерело. Вкажіть місце у ньому та перевірте застосовність.");}
 void LoadReferenceExample(object sender,RoutedEventArgs e){ClearTerm(sender,e);Form.Text="ø";Lemma.Text="samogłoska nosowa";Meaning.Text="Позначення короткого носового голосного у пропозиції Паркошовіца.";TermLanguage.Text="pl";TermPeriod.Text="XV ст.";TermKind.SelectedItem=TermKind.Items.Cast<ComboBoxItem>().First(i=>i.Tag.ToString()=="orthography");TermNote.Text=T("Приклад не застосовано до документа. Перевірте час, мову й почерк.");ReadReference(new JsonObject{["title"]="Jakub Parkoszowic — Traktat o ortografii polskiej (академічний опис UW)",["url"]="https://gramatyki.uw.edu.pl/book/3",["locator"]="Характеристика → Traktat o ortografii; абзац про голосні",["resource_type"]="Academic description of a historical orthography proposal",["work_period"]="близько 1440",["witness_period"]="Збережена копія копії; тут не датована",["edition_period"]="Сучасний академічний опис",["scope"]="Проєкт письма Паркошовіца; не загальна практика XV ст. і не правило латинських метрик XVIII ст.",["authenticity"]="Опис пропозиції реформи, не універсальна норма"});TermChecked.IsChecked=false;Status.Text=T("Приклад не застосовано до документа. Перевірте час, мову й почерк.");}
 async void SaveTerm(object sender,RoutedEventArgs e)=>await Run(async()=>{var selected=(Terms.SelectedItem as Row)?.Data;var target=selected?["page"]?.ToString()??page;var context=target==page?snapshot:(await Call("historical_get",new(){["page"]=target})).AsObject();await Call("historical_term",new(){["page"]=target,["term"]=selected?["id"]?.ToString(),["annotation"]=selected?["annotation"]?.ToString(),["expected"]=context?["signature"]?.ToString(),["form"]=Form.Text,["lemma"]=Lemma.Text,["meaning"]=Meaning.Text,["concept"]=Concept.Text,["language"]=TermLanguage.Text,["period"]=TermPeriod.Text,["writer"]=TermWriter.Text,["kind"]=((ComboBoxItem)TermKind.SelectedItem).Tag.ToString(),["note"]=TermNote.Text,["reference"]=TermReference(),["checked"]=TermChecked.IsChecked==true});await Reload();TermChecked.IsChecked=false;ReferenceChecked.IsChecked=false;Status.Text=T("Збережено");});
 async void SaveDecision(object sender,RoutedEventArgs e)=>await Run(async()=>{if(analysis==null||Annotation==null)return;await Call("historical_decide",new(){["page"]=page,["annotation"]=Annotation,["signature"]=analysis["signature"]?.ToString(),["reading"]=Reading.Text,["interpretation"]=Interpretation.Text,["note"]=DecisionNote.Text,["checked"]=DecisionChecked.IsChecked==true,["uncertain"]=Uncertain.IsChecked==true});await Reload();Status.Text=T("Збережено");});
 static void ShowImage(Image target,string? path,JsonArray? rect=null){if(string.IsNullOrEmpty(path)||!System.IO.File.Exists(path)){target.Source=null;return;}var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(path);image.EndInit();image.Freeze();if(rect==null){target.Source=image;return;}int x=Math.Clamp((int)(rect[0]!.GetValue<double>()*image.PixelWidth),0,image.PixelWidth-1),y=Math.Clamp((int)(rect[1]!.GetValue<double>()*image.PixelHeight),0,image.PixelHeight-1),w=Math.Clamp((int)(rect[2]!.GetValue<double>()*image.PixelWidth),1,image.PixelWidth-x),h=Math.Clamp((int)(rect[3]!.GetValue<double>()*image.PixelHeight),1,image.PixelHeight-y);target.Source=new CroppedBitmap(image,new Int32Rect(x,y,w,h));}
 static string Bounds(JsonArray rect)=>string.Join(" · ",rect.Select(n=>n!.GetValue<double>().ToString("0.000",CultureInfo.InvariantCulture)));
 void PickLayout(object sender,RoutedEventArgs e){if(sourcePath==null)return;var picker=new RegionPicker(sourcePath){Owner=this};if(picker.ShowDialog()!=true||picker.Bounds is not JsonArray picked)return;layoutRect=picked;LayoutBounds.Text=Bounds(layoutRect);LayoutChecked.IsChecked=false;ShowImage(LayoutPreview,sourcePath,layoutRect);}
 async void ProposeStructure(object sender,RoutedEventArgs e)=>await Run(LoadProposals);
 async Task LoadProposals(){var result=await Call("historical_structure_propose",new(){["page"]=page});Proposals.ItemsSource=Array(result,"candidates").Select(n=>new Row(n!.AsObject(),T("Можлива сітка таблиці")+" · "+(n["rect"] is JsonArray rect?Bounds(rect):""))).ToList();Status.Text=T(Proposals.Items.Count==0?"Сітки таблиці не запропоновано. Можна виділити ділянку вручну.":"Перевірте межі підказки перед збереженням.");}
 void SelectProposal(object sender,SelectionChangedEventArgs e){if(Proposals.SelectedItem is not Row row||row.Data["rect"] is not JsonArray rect)return;layoutRect=rect.DeepClone().AsArray();LayoutRole.SelectedIndex=1;LayoutBounds.Text=Bounds(layoutRect);LayoutChecked.IsChecked=false;ShowImage(LayoutPreview,sourcePath,layoutRect);}
 async void SaveLayout(object sender,RoutedEventArgs e)=>await Run(async()=>{if(layoutRect==null){Status.Text=T("Спочатку виділіть ділянку.");return;}await Call("historical_layout",new(){["page"]=page,["expected"]=snapshot?["signature"]?.ToString(),["role"]=((ComboBoxItem)LayoutRole.SelectedItem).Tag.ToString(),["rect"]=layoutRect.DeepClone(),["note"]=LayoutNote.Text,["checked"]=LayoutChecked.IsChecked==true});await Reload();LayoutChecked.IsChecked=false;Status.Text=T("Збережено");});
 void PickExemplar(object sender,RoutedEventArgs e){if(cropPath==null||Value(analysis?["original"],"kind")!="line"||analysis?["original"]?["rect"] is not JsonArray parent){Status.Text=T("Спочатку виберіть розмічений рядок.");return;}var picker=new RegionPicker(cropPath){Owner=this};if(picker.ShowDialog()!=true||picker.Bounds is not JsonArray r)return;exemplarRect=new JsonArray(parent[0]!.GetValue<double>()+r[0]!.GetValue<double>()*parent[2]!.GetValue<double>(),parent[1]!.GetValue<double>()+r[1]!.GetValue<double>()*parent[3]!.GetValue<double>(),r[2]!.GetValue<double>()*parent[2]!.GetValue<double>(),r[3]!.GetValue<double>()*parent[3]!.GetValue<double>());ExemplarBounds.Text=Bounds(exemplarRect);ExemplarChecked.IsChecked=false;ShowImage(ExemplarPreview,cropPath,r);}
 async void SaveExemplar(object sender,RoutedEventArgs e)=>await Run(async()=>{if(exemplarRect==null||Annotation==null){Status.Text=T("Спочатку виділіть зразок у рядку.");return;}var result=await Call("historical_exemplar",new(){["page"]=page,["expected"]=snapshot?["signature"]?.ToString(),["annotation"]=Annotation,["rect"]=exemplarRect.DeepClone(),["label"]=ExemplarLabel.Text,["note"]=ExemplarNote.Text,["checked"]=ExemplarChecked.IsChecked==true});await Reload();ShowImage(ExemplarPreview,Value(result,"path"));ExemplarChecked.IsChecked=false;Status.Text=T("Збережено");});
 void SelectExemplar(object sender,SelectionChangedEventArgs e){if(Exemplars.SelectedItem is Row row){ShowImage(ExemplarPreview,Value(row.Data,"path"));ExemplarLabel.Text=Value(row.Data,"label");ExemplarNote.Text=Value(row.Data,"note");ExemplarChecked.IsChecked=false;}}
 void SelectHandReference(object sender,SelectionChangedEventArgs e){if(HandReferences.SelectedItem is not Row row)return;bool applicable=row.Data["applicable"]?.GetValue<bool>()==true;HandStatus.Text=(applicable?T("Зразок для ручного порівняння рисок."):T("Зразок застарів або не відповідає поточному контексту."))+"\n"+Value(row.Data,"note");ShowImage(HandSample,applicable?Value(row.Data,"path"):null);}
}
